const fs = require('fs');
const path = require('path');

// The extension's Word export is the CLI's writer: the src/core modules it needs, wrapped
// into one classic script (extension/lib/docx-export.js) that defines `MdPdfDocx`. No tool
// and no network: each module becomes a function in a small require() table. `marked` is
// the copy the page already loads; the Node-only modules get stand-ins that the browser
// path never calls (pictures come from the page, deflate from CompressionStream).
// `npm run fetch:libs` writes the file; a test checks that it matches this output.

const coreDir = path.join(__dirname, '..', 'src', 'core');
const MODULES = ['docx-browser', 'docx', 'docmodel', 'frontmatter', 'footnotes', 'preprocess', 'math', 'omml', 'zip'];
const STAND_INS = {
  marked: 'module.exports = scope.marked;',
  images: 'module.exports = { readLocalImage: function () { return null; } };',
  zlib: 'module.exports = {};'
};

function bundleDocx() {
  const read = name => fs.readFileSync(path.join(coreDir, `${name}.js`), 'utf8').replace(/\r\n/g, '\n').trimEnd();
  const unknown = new Set();
  const definitions = MODULES.map(name => {
    const source = read(name);
    for (const [, id] of source.matchAll(/require\('([^']+)'\)/g)) {
      const key = id.replace(/^\.\//, '');
      if (!MODULES.includes(key) && !STAND_INS[key]) unknown.add(`${id} (in ${name}.js)`);
    }
    return `  ${JSON.stringify(name)}: function (module, exports, require) {\n${source}\n  }`;
  });
  if (unknown.size) throw new Error(`bundle-docx: no module or stand-in for ${[...unknown].join(', ')}`);
  const standIns = Object.entries(STAND_INS).map(
    ([name, body]) => `  ${JSON.stringify(name)}: function (module) {\n    ${body}\n  }`
  );

  return `/*! SPDX-License-Identifier: MIT | Copyright (c) 2026 Van Nguyen | github.com/vannt-dev/convert-md-to-pdf */
// Generated by scripts/bundle-docx.js from src/core (npm run fetch:libs). Do not edit.
(function (scope) {
var definitions = {
${[...definitions, ...standIns].join(',\n')}
};
var cache = {};
function load(id) {
  var name = id.replace(/^\\.\\//, '');
  if (!cache[name]) {
    var module = { exports: {} };
    cache[name] = module;
    definitions[name](module, module.exports, load);
  }
  return cache[name].exports;
}
scope.MdPdfDocx = load('docx-browser');
})(typeof globalThis !== 'undefined' ? globalThis : this);
`;
}

module.exports = { bundleDocx };

if (require.main === module) {
  const target = path.join(__dirname, '..', 'extension', 'lib', 'docx-export.js');
  fs.writeFileSync(target, bundleDocx());
  console.log(`✔ ${path.relative(process.cwd(), target)}`);
}
